/**
 * @name Zip extraction member filename reaching filesystem path (potential Zip Slip)
 * @description Archive member filenames flowing into filesystem path sinks without sanitization can lead to path traversal (Zip Slip).
 * @kind path-problem
 * @problem.severity warning
 * @id py/virtualenv/zip-slip
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(Attribute attr |
      attr.getName() = "filename" and
      source = DataFlow::exprNode(attr)
    )
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Archive member filename flows to filesystem path $@.", source.getNode(), "member filename"

/**
 * @name Command injection via subprocess
 * @description Untrusted input flowing to subprocess command execution
 * @kind problem
 * @problem.severity error
 * @id py/virtualenv/cmd-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CmdInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember(["Popen", "run", "call", "check_call", "check_output", "getoutput", "getstatusoutput"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module CmdInjectionFlow = TaintTracking::Global<CmdInjectionConfig>;

from DataFlow::Node source, DataFlow::Node sink
where CmdInjectionFlow::flow(source, sink)
select sink, "Command injection: untrusted data flows to subprocess command $@.", source, "source"
